"""Document search index."""

from elasticsearch import Elasticsearch

from config import ELASTICSEARCH_URL

INDEX = "doc_search"
es = Elasticsearch(ELASTICSEARCH_URL)


def index_document(user, document):
    es.index(
        index=INDEX,
        document={
            "owner_email": user.email,
            "title": document.title,
        },
    )

"""Event publishing."""

import json

import pika

from config import RABBITMQ_URL

QUEUE = "events"
channel = pika.BlockingConnection(pika.URLParameters(RABBITMQ_URL)).channel()


def publish_document_created(user):
    channel.basic_publish(
        exchange="",
        routing_key=QUEUE,
        body=json.dumps(
            {
                "email": user.email,
            }
        ),
    )

"""Small string helpers. No personal data passes through this module."""


def slugify(value):
    return "-".join(part for part in value.lower().split() if part)


def truncate(value, limit=80):
    if len(value) <= limit:
        return value
    return value[: limit - 3] + "..."


def humanise_bytes(count):
    for unit in ("B", "KB", "MB"):
        if count < 1024:
            return f"{count} {unit}"
        count //= 1024
    return f"{count} GB"
